import{_ as t}from"./chunks/login.D00YWU-l.js";import{_ as a}from"./chunks/policy-new-vulnerability.BuxOrLYz.js";import{_ as s}from"./chunks/registry-npm.BCP6_0bm.js";import{_ as i,o,c as n,a3 as r}from"./chunks/framework.Ki30n65y.js";const f=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),l={name:"guide/quick-start.md"};function h(p,e,c,d,g,u){return o(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>In about ten minutes you will run DepGate on one machine, connect npm to it, and watch it block a vulnerable package. This setup is for evaluation. For a production installation, follow <a href="/depgate/install/docker">Install with Docker</a>.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>You need:</p><ul><li>A Linux or macOS machine with <strong>Docker Engine</strong> and <strong>Docker Compose v2</strong>.</li><li><strong>Git</strong> and <strong>OpenSSL</strong>.</li><li>Outbound internet access, so DepGate can reach the public registries.</li><li>Ports <strong>80</strong> and <strong>443</strong> free on the machine.</li><li><strong>Node.js and npm</strong>, to try an install at the end.</li></ul><h2 id="step-1-get-depgate" tabindex="-1">Step 1: Get DepGate <a class="header-anchor" href="#step-1-get-depgate" aria-label="Permalink to &quot;Step 1: Get DepGate&quot;">​</a></h2><p>Clone the repository and change to the all-in-one folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/secmods/depgate.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depgate/deploy/all-in-one</span></span></code></pre></div><h2 id="step-2-start-everything" tabindex="-1">Step 2: Start everything <a class="header-anchor" href="#step-2-start-everything" aria-label="Permalink to &quot;Step 2: Start everything&quot;">​</a></h2><p>The quick-start script writes a configuration file with generated secrets, creates a local certificate authority and an HTTPS certificate for <code>localhost</code>, and starts PostgreSQL, Redis and DepGate from their published images:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./quickstart.sh</span></span></code></pre></div><p>The first run pulls the images. When it finishes, the script checks that DepGate answers and prints the address and the admin account.</p><div class="tip custom-block"><p class="custom-block-title">Running a different version?</p><p><code>docker-compose.yml</code> takes the image from <code>.env</code>: <code>DEPGATE_IMAGE</code> (the image, <code>secmods/depgate</code> on Docker Hub by default) and <code>DEPGATE_VERSION</code> (the tag). To run another version or an image from your own registry, set them before the first run, <code>DEPGATE_VERSION=1.0.1 ./quickstart.sh</code>, or edit <code>.env</code> afterwards and run <code>./3-run.sh</code>.</p></div><h2 id="step-3-sign-in" tabindex="-1">Step 3: Sign in <a class="header-anchor" href="#step-3-sign-in" aria-label="Permalink to &quot;Step 3: Sign in&quot;">​</a></h2><ol><li>Open <strong><a href="https://localhost" target="_blank" rel="noreferrer">https://localhost</a></strong> in your browser. The certificate comes from the local CA the script created; accept it, or import <code>deploy/all-in-one/certs/ca.crt</code> into your browser&#39;s trust store.</li><li>Sign in as <code>admin@example.com</code>. The password is <code>ADMIN_PASSWORD</code> in <code>deploy/all-in-one/.env</code>.</li></ol><p><img src="`+t+'" alt="The DepGate sign-in page"></p><p>You land on the <strong>Dashboard</strong>. It is empty until packages flow through the gateway.</p><p>The sidebar on the left lists every page. To get more room, choose the arrow on its edge: the sidebar shrinks to icons, and hovering an icon shows its name. Choose the arrow again to expand it. Your browser remembers the choice. On a phone or small window, the sidebar opens from the menu button instead.</p><h2 id="step-4-look-at-the-policies" tabindex="-1">Step 4: Look at the policies <a class="header-anchor" href="#step-4-look-at-the-policies" aria-label="Permalink to &quot;Step 4: Look at the policies&quot;">​</a></h2><p>In the sidebar, choose <strong>Policies</strong>. A new installation starts with eight <a href="/depgate/admin/policies#starter-policies">starter policies</a>. Four enforce, among them <strong>Critical vulnerabilities</strong>, which blocks versions with a vulnerability scored CVSS 9.0 or higher; four only monitor.</p><p>To add a policy of your own:</p><ol><li>Choose <strong>New policy</strong>.</li><li><strong>Name</strong>: <code>High vulnerabilities in production</code>.</li><li>Under <strong>Rule</strong>, choose <strong>Vulnerability</strong>, and set <strong>CVSS score at least</strong> to <code>7.0</code>.</li><li>Under <strong>Enforcement</strong>, choose <strong>Monitor only (log, don&#39;t block)</strong> to see what it would block before it blocks anything.</li><li>Choose <strong>Create policy</strong>.</li></ol><p><img src="'+a+'" alt="Creating a vulnerability policy"></p><p><a href="/depgate/admin/create-policy">Create a policy</a> explains every field.</p><h2 id="step-5-connect-npm" tabindex="-1">Step 5: Connect npm <a class="header-anchor" href="#step-5-connect-npm" aria-label="Permalink to &quot;Step 5: Connect npm&quot;">​</a></h2><ol><li><p>In the sidebar, choose <strong>Registry</strong>. The <strong>npm</strong> tab shows a ready-made <code>.npmrc</code> with your personal registry token.</p></li><li><p>Choose <strong>Copy snippet</strong>.</p></li><li><p>Create an empty folder, and save the snippet in it as <code>.npmrc</code>.</p></li><li><p>npm must trust the local CA. In the same folder, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cafile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/deploy/all-in-one/certs/ca.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --location=project</span></span></code></pre></div></li></ol><p><img src="'+s+'" alt="The Registry page with the npm snippet"></p><h2 id="step-6-install-a-package" tabindex="-1">Step 6: Install a package <a class="header-anchor" href="#step-6-install-a-package" aria-label="Permalink to &quot;Step 6: Install a package&quot;">​</a></h2><p>Install a current, healthy version. DepGate allows it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> express</span></span></code></pre></div><p>Now install a version with a known critical vulnerability:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimist@1.2.5</span></span></code></pre></div><p>npm fails with <code>403 Forbidden</code>. The response names the policy and the vulnerability that matched, and links to Package check, which shows the newest version you can use instead.</p><h2 id="step-7-see-the-decisions" tabindex="-1">Step 7: See the decisions <a class="header-anchor" href="#step-7-see-the-decisions" aria-label="Permalink to &quot;Step 7: See the decisions&quot;">​</a></h2><ul><li><strong>Dashboard</strong> counts the allowed and blocked requests.</li><li><strong>Decision Ledger</strong> lists the blocked install. Expand it to see the policy, the vulnerability and who made the request.</li><li><strong>Package check</strong> (<code>minimist</code>, npm) shows every recent version of the package, which ones are allowed, and why the others are blocked.</li></ul><h2 id="clean-up" tabindex="-1">Clean up <a class="header-anchor" href="#clean-up" aria-label="Permalink to &quot;Clean up&quot;">​</a></h2><p>To stop DepGate and its database (the data is kept):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./3-run.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stop</span></span></code></pre></div><p><code>docker compose down -v</code> in the same folder also deletes the database data and the artifact cache.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/depgate/admin/policies">Policies overview</a>: plan the policies your organization needs.</li><li><a href="/depgate/admin/monitoring">Monitor before enforcing</a>: roll out broad rules without breaking builds.</li><li><a href="/depgate/developers/connect-package-managers">Connect your package manager</a>: settings for every ecosystem.</li><li><a href="/depgate/install/docker">Install with Docker</a>: a production installation with your own certificate and database.</li></ul>',41)])])}const v=i(l,[["render",h]]);export{f as __pageData,v as default};
